enum map_e
{
    MAP_DIFFUSE
};

class mat_fac
{
public:
    virtual ~mat_fac();
    void load_material(const stringx &file);
    int get_original_width(int frame, map_e map = MAP_DIFFUSE) const;
    int get_original_height(int frame, map_e map = MAP_DIFFUSE) const;

private:
    char material[0x108];
} __attribute__((aligned(8)));

class vector2d
{
public:
    rational_t x;
    rational_t y;

    vector2d() {}
    vector2d(rational_t new_x, rational_t new_y) : x(new_x), y(new_y) {}
};

class rectf
{
public:
    vector2d tl;
    vector2d br;

    rectf() {}
    rectf(rational_t left, rational_t top, rational_t right, rational_t bottom)
        : tl(left, top), br(right, bottom) {}
};

class widget
{
    char padding0[0x14];

protected:
    unsigned int flags;
    char padding1[0x118];
    rectf subrect;
    void *vtable;

    void set_flag(unsigned int flag, bool value)
    {
        if (value)
            flags |= flag;
        else
            flags &= ~flag;
    }
};

class bitmap_widget : public widget
{
public:
    bool open(const char *name);
    void set_tc();

protected:
    rational_t w;
    rational_t h;
    rational_t hw;
    rational_t hh;
    int nframes;
    mat_fac mat;
    int index;
    bool playing;
    rational_t frame_delay;
    rational_t frame_time;
    rational_t last_time;
};

