bool bitmap_widget::open(const char *name)
{
    mat.load_material(name);
    w = mat.get_original_width(0, MAP_DIFFUSE);
    h = mat.get_original_height(0, MAP_DIFFUSE);

    set_flag(0x00000002, true);
    hw = w * 0.5f;
    hh = h * 0.5f;
    subrect = rectf(0.0f, 0.0f, w, h);
    set_tc();
    last_time = 0;
    return true;
}
